// Monta o resumo diário (texto para WhatsApp e HTML para e-mail).
const cfg = $('Configuração').first().json;
const row = $('Buscar prazos').first().json;
const parse = (v) => (typeof v === 'string' ? JSON.parse(v) : v);
const itens = parse(row.itens) || [];
const perfil = parse(row.perfil) || {};

if (!itens.length && !cfg.enviar_quando_vazio) return [];

const ROTULO = {
  entrega: 'Postagem', prazo_marca: 'Entrega p/ marca', publicacao: 'Publicação',
  tarefa: 'Tarefa', recebimento: 'Recebimento',
};
const EMOJI = { entrega: '📲', prazo_marca: '📦', publicacao: '📣', tarefa: '✅', recebimento: '💰' };
const SEMANA = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'];
const fmtData = (iso) => {
  const [a, m, d] = iso.split('-').map(Number);
  return `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')} (${SEMANA[new Date(Date.UTC(a, m - 1, d)).getUTCDay()]})`;
};
const brl = (v) => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const appUrl = String(cfg.app_url || '').replace(/\/+$/, '');

const grupos = [
  { titulo: '🔴 Atrasados', filtro: (i) => i.dias < 0 },
  { titulo: '🟠 Hoje', filtro: (i) => i.dias === 0 },
  { titulo: '🟡 Amanhã', filtro: (i) => i.dias === 1 },
  { titulo: `🟢 Próximos ${cfg.dias} dias`, filtro: (i) => i.dias > 1 },
].map((g) => ({ ...g, itens: itens.filter(g.filtro) })).filter((g) => g.itens.length);

const descricao = (i) => {
  const quem = [i.marca, i.campanha].filter(Boolean).join(' — ') || 'Sem campanha';
  const extra = [i.hora, i.valor != null ? brl(i.valor) : null].filter(Boolean).join(' · ');
  // Postagens e tarefas levam o tipo na frente; os demais já se explicam.
  const oque = ['entrega', 'tarefa'].includes(i.tipo) ? `${ROTULO[i.tipo]}: ${i.titulo}` : i.titulo;
  return { quem, extra, oque };
};

// WhatsApp
const nome = (perfil.nome || '').split(' ')[0];
const linhas = [`*Resumo das publis${nome ? ', ' + nome : ''}* · ${fmtData(row.hoje)}`, ''];
if (!grupos.length) linhas.push(`Nada vencendo nos próximos ${cfg.dias} dias. 🎉`);
for (const g of grupos) {
  linhas.push(`*${g.titulo}*`);
  for (const i of g.itens) {
    const { quem, extra, oque } = descricao(i);
    linhas.push(`${EMOJI[i.tipo]} ${fmtData(i.data)} · *${quem}*`);
    linhas.push(`   ${oque}${extra ? ' · ' + extra : ''}`);
  }
  linhas.push('');
}
const aReceber = itens.filter((i) => i.tipo === 'recebimento').reduce((s, i) => s + Number(i.valor || 0), 0);
if (aReceber) linhas.push(`💰 A receber no período (inclui atrasados): *${brl(aReceber)}*`);
if (appUrl) linhas.push(`Abrir agenda: ${appUrl}/#/calendario`);
const whatsapp = linhas.join('\n').trim();

// E-mail
const linhaHtml = (i) => {
  const { quem, extra, oque } = descricao(i);
  const link = appUrl && i.publi_id ? `${appUrl}/#/campanhas/${i.publi_id}` : '';
  const q = link ? `<a href="${esc(link)}" style="color:#7c3aed;text-decoration:none">${esc(quem)}</a>` : esc(quem);
  return `<tr>
    <td style="padding:8px;border-bottom:1px solid #eee;white-space:nowrap">${fmtData(i.data)}</td>
    <td style="padding:8px;border-bottom:1px solid #eee">${EMOJI[i.tipo]} ${ROTULO[i.tipo]}</td>
    <td style="padding:8px;border-bottom:1px solid #eee"><strong>${q}</strong><br><span style="color:#555">${esc(oque)}${extra ? ' · ' + esc(extra) : ''}</span></td>
  </tr>`;
};
const corpo = grupos.length
  ? grupos.map((g) => `<h3 style="margin:24px 0 8px">${g.titulo} (${g.itens.length})</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px">${g.itens.map(linhaHtml).join('')}</table>`).join('')
  : `<p>Nada vencendo nos próximos ${cfg.dias} dias. 🎉</p>`;
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:auto;color:#222">
  <h2 style="margin-bottom:4px">Resumo das publis${nome ? ', ' + esc(nome) : ''}</h2>
  <p style="color:#666;margin-top:0">${fmtData(row.hoje)} · prazos até ${cfg.dias} dias</p>
  ${corpo}
  ${aReceber ? `<p style="margin-top:24px">💰 A receber no período (inclui atrasados): <strong>${brl(aReceber)}</strong></p>` : ''}
  ${appUrl ? `<p><a href="${esc(appUrl)}/#/calendario" style="color:#7c3aed">Abrir a agenda</a></p>` : ''}
</div>`;

const atrasados = itens.filter((i) => i.dias < 0).length;
const assunto = `Publis: ${itens.length} prazo${itens.length === 1 ? '' : 's'} nos próximos ${cfg.dias} dias`
  + (atrasados ? ` (${atrasados} atrasado${atrasados === 1 ? '' : 's'})` : '');

// Destinos: configuração ou, se vazio, os dados do perfil no app.
const emailPara = String(cfg.email_para || perfil.email || '').trim();
const numeros = String(cfg.whatsapp_numeros || perfil.whatsapp || '')
  .split(/[,;]/).map((n) => n.trim()).filter(Boolean)
  .map((n) => {
    if (n.includes('@')) return n; // grupo/JID do WhatsApp
    const d = n.replace(/\D/g, '');
    return d.length === 10 || d.length === 11 ? '55' + d : d;
  });

const base = { assunto, html, whatsapp, email_para: emailPara, total: itens.length, atrasados };
return numeros.length
  ? numeros.map((numero) => ({ json: { ...base, numero } }))
  : [{ json: { ...base, numero: null } }];
